#!/bin/sh
# SPDX-License-Identifier: Apache-2.0
# Regenerate protobuf code for Go (reflopd), the Python worker and the Python
# client. Generated files are committed so that building needs no protoc.
#
#   PROTOC=/path/to/protoc PROTOC_GEN_GO=/path/to/protoc-gen-go codegen/gen_proto.sh
#
# Use protoc 29.x: its Python gencode works with protobuf runtimes 5.29 and 6.x.
set -eu
cd "$(dirname "$0")/.."
PROTOC=${PROTOC:-protoc}
PROTOC_GEN_GO=${PROTOC_GEN_GO:-$(command -v protoc-gen-go)}

case "$("$PROTOC" --version)" in
	"libprotoc 29."*) ;;
	*) echo "gen_proto: need protoc 29.x, got: $("$PROTOC" --version)" >&2; exit 1 ;;
esac

go_out=pkg
rm -rf "$go_out/reflopv1"
mkdir -p "$go_out"
"$PROTOC" -I proto --plugin=protoc-gen-go="$PROTOC_GEN_GO" \
	--go_out="$go_out" --go_opt=module=github.com/chaseungjoon/reflop/pkg \
	proto/reflop/v1/*.proto

for dst in server/worker/reflop_worker/_pb client/python/reflop/_pb; do
	rm -rf "$dst"
	mkdir -p "$dst"
	tmp=$(mktemp -d)
	"$PROTOC" -I proto --python_out="$tmp" proto/reflop/v1/*.proto
	for f in "$tmp"/reflop/v1/*_pb2.py; do
		# Make imports package-relative so the code works inside any package.
		sed -e 's/^from reflop\.v1 import \(.*\)_pb2 as /from . import \1_pb2 as /' "$f" > "$dst/$(basename "$f")"
	done
	rm -rf "$tmp"
	printf '# SPDX-License-Identifier: Apache-2.0\n# Generated by codegen/gen_proto.sh. Do not edit.\n' > "$dst/__init__.py"
done
echo "gen_proto: ok"
